import {KEY,initial,questions,completeTest,sendInvitation,canSeeContact} from './state.mjs';
let state;try{state=JSON.parse(localStorage.getItem(KEY))||initial();}catch{state=initial();}let notice='';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const field=(label,name,value='',type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" required></label>`;
const money=x=>Number(x).toLocaleString('ru-RU');
const all=()=>[state.profile,...state.candidates];
const save=()=>{localStorage.setItem(KEY,JSON.stringify(state));render();};
function heading(kicker,title,text){return `<p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="lead">${text}</p>${notice?`<div class="notice" role="status">${esc(notice)}</div>`:''}`;}
function profile(){const p=state.profile;return heading('ШАГ 01 · ПРОФИЛЬ','Покажите, что вы умеете','Работодатель найдёт вас по подтверждённой категории. Контакты появятся после вашего согласия.')+`<div class="grid"><form id="profile" class="card">${field('Имя','name',p.name)}${field('Город','city',p.city)}${field('Навыки','skills',p.skills)}<label class="check"><input type="checkbox" name="visible" ${p.visible?'checked':''}> Разрешить публикацию профиля</label><button class="primary">Сохранить профиль</button><button type="button" data-action="ai">Помочь с описанием · мок AI</button></form><div><div class="card"><span class="pill">${esc(p.grade||'Категория ещё не подтверждена')}</span><h2>Проверка навыков</h2><p>Короткий демонстрационный тест: четыре вопроса. Это имитация оценивания.</p><button data-view="test" class="primary">Перейти к тесту</button></div><div class="card"><h2>Демо регистрация</h2><p>Адрес: alexey@demo.invalid</p><p>${state.verified?'Демонстрационный email подтверждён':'Подтверждение имитируется без отправки письма.'}</p><button data-action="verify">Подтвердить demo email</button></div></div></div>`;}
function test(){return heading('ШАГ 02 · ТЕСТ','Подтвердите категорию','Правильные ответы и результат здесь — моки. Для демонстрации достаточно трёх правильных ответов из четырёх.')+`<form id="test" class="card"><label>Категория<select name="grade"><option>Junior</option><option>Middle</option></select></label>${questions.map((q,i)=>`<fieldset><legend>${i+1}. ${q.text}</legend>${q.options.map((o,j)=>`<label class="choice"><input required type="radio" name="q${i}" value="${j}">${o}</label>`).join('')}</fieldset>`).join('')}<button class="primary">Завершить тест</button></form>`;}
function result(){const r=state.result;return heading('ШАГ 03 · РЕЗУЛЬТАТ',r?.passed?'Категория подтверждена':'Попробуйте ещё раз','Это результат демонстрационного теста, а не профессиональная аттестация.')+`<div class="card"><div class="big-number">${r?.score??0}<small> / 4</small></div><h2>${esc(r?.grade||'Junior')}</h2><p>${r?.passed?'Профиль теперь доступен в поиске по категории.':'Предыдущая категория сохранена. В прототипе можно повторить без ожидания.'}</p><button data-role="employer" class="primary">Посмотреть глазами работодателя</button><button data-view="test">Повторить демо</button></div>`;}
function candidates(){const items=all().filter(p=>p.grade===state.filter&&(p.id!==1||p.visible));return heading('КАБИНЕТ РАБОТОДАТЕЛЯ','Найдите разработчика','Категория подтверждена тестом. Достижения ФСП — дополнительный сигнал, не повышение категории.')+`<form id="filter" class="filters"><label>Категория<select name="grade"><option ${state.filter==='Junior'?'selected':''}>Junior</option><option ${state.filter==='Middle'?'selected':''}>Middle</option></select></label><button>Применить</button></form><div class="cards">${items.map(p=>`<article class="card"><span class="pill">${p.grade}</span><h2>${esc(p.name)}</h2><p>${esc(p.city)} · ${esc(p.skills)}</p><p>Тест: ${p.score}% · ФСП: ${p.fsp? 'демо участие':'нет истории'}</p><button data-candidate="${p.id}" class="primary">Профиль и предложение</button></article>`).join('')||'<div class="card">Никого не найдено. Фильтр сохранён. Пройдите тест кандидатом или выберите другую категорию.</div>'}</div>`;}
function detail(){const p=all().find(p=>p.id===state.selected);return heading('ПРОФИЛЬ КАНДИДАТА',esc(p.name),`${esc(p.grade||'Без категории')} · ${esc(p.skills)}`)+`<div class="grid"><div class="card"><h2>Контакты</h2><p data-testid="contact">${canSeeContact(state,p.id)?esc(p.contact):'Скрыты до принятия вашего предложения'}</p><p>Публичные данные и контакты здесь вымышлены.</p><button data-view="candidates">Назад к поиску</button></div><form id="invitation" class="card"><h2>Предложить работу</h2><input type="hidden" name="candidate" value="${p.id}">${field('Роль','title','iOS разработчик')}${field('Зарплата от, ₽ до налогов / месяц','min',120000,'number')}${field('Зарплата до, ₽ до налогов / месяц','max',180000,'number')}${field('Задачи и следующий шаг','tasks','Развитие приложения; знакомство с командой')}<button class="primary">Отправить предложение</button></form></div>`;}
function invitations(){const items=state.role==='candidate'?state.invitations.filter(i=>i.candidate===1):state.invitations;return heading('ПРЕДЛОЖЕНИЯ','Решение остаётся за кандидатом','Принятие открывает вымышленные контакты отправителю. Отказ сохраняет их скрытыми.')+`<div class="cards">${items.map(i=>`<article class="card"><span class="pill">${({sent:'Ожидает решения',accepted:'Принято',declined:'Отклонено'})[i.status]}</span><h2>${esc(i.title)}</h2><p>${esc(i.company)} · ${money(i.min)}–${money(i.max)} ₽ / месяц до налогов</p><p>${esc(i.tasks)}</p>${state.role==='candidate'&&i.status==='sent'?`<button class="primary" data-accept="${i.id}">Принять предложение</button><button data-decline="${i.id}">Отклонить</button>`:''}${state.role==='employer'?`<button data-candidate="${i.candidate}">Открыть профиль</button>`:''}</article>`).join('')||'<div class="card"><h2>Пока нет предложений</h2><p>Перейдите в роль работодателя и отправьте предложение кандидату.</p></div>'}</div>`;}
function render(){document.querySelectorAll('[data-role]').forEach(b=>b.classList.toggle('active',b.dataset.role===state.role));const links=state.role==='candidate'?[['profile','01 · Профиль'],['test','02 · Тест'],['invitations','03 · Предложения']]:[['candidates','01 · Поиск'],['invitations','02 · Предложения']];document.querySelector('#nav').innerHTML=links.map(([view,text])=>`<button data-view="${view}" class="${state.view===view?'active':''}">${text}</button>`).join('');document.querySelector('#content').innerHTML=({profile,test,result,candidates,detail,invitations}[state.view]||profile)();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.role){state.role=b.dataset.role;state.view=state.role==='candidate'?'profile':'candidates';notice='';save();}else if(b.dataset.view){state.view=b.dataset.view;notice='';save();}else if(b.dataset.candidate){state.selected=Number(b.dataset.candidate);state.view='detail';notice='';save();}else if(b.dataset.accept||b.dataset.decline){const i=state.invitations.find(i=>i.id===Number(b.dataset.accept||b.dataset.decline));i.status=b.dataset.accept?'accepted':'declined';save();}else if(b.dataset.action==='reset'){state=initial();notice='Демонстрация сброшена.';save();}else if(b.dataset.action==='verify'){state.verified=true;notice='Demo email подтверждён — это имитация.';save();}else if(b.dataset.action==='ai'){notice='Мок ответа AI: «iOS разработчик. Создаю интерфейсы на SwiftUI, изучаю архитектуру и асинхронность». Внешний сервис не вызывался.';save();}});
document.addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));notice='';if(e.target.id==='profile'){Object.assign(state.profile,{name:data.name,city:data.city,skills:data.skills,visible:data.visible==='on'});notice='Профиль сохранён.';}if(e.target.id==='test'){completeTest(state,[data.q0,data.q1,data.q2,data.q3],data.grade);state.view='result';}if(e.target.id==='filter')state.filter=data.grade;if(e.target.id==='invitation'){try{sendInvitation(state,data);notice='Предложение отправлено. Переключитесь в роль кандидата.';}catch(err){notice=err.message;}}save();});render();
